        "f7_full": "都立大学駅から緩やかな坂道を上がると、閑静な住宅街のなかに白いアートスペースが現れる。ここは「柿の木坂」。かつて大きな柿の木がそびえていたとも、柿の実を積んだ荷車を押し上げたとも伝わる坂の街に、今は最先端の現代アートが息づいている。\n\n住宅街の静けさのなかに突然開ける、白い壁と自然光が美しいホワイトキューブの展示空間。\n\n展示空間を出たら、目黒通りを渡って丘の上へ。駅名「都立大学」の正体が眠る場所へ向かおう。",
