        "f7_full": "堀之内貝塚の西隣に建つ『市立市川考古博物館』（入館無料）と、すぐ隣の『市立市川歴史博物館』。ここには、先ほど歩いた堀之内貝塚から出土した優美な曲線を持つ『堀之内式土器』や巨大な貝層の剥ぎ取り標本、さらにはこれから向かう『下総国分寺・国分尼寺』の軒丸瓦や墨書土器が一堂に展示されている。縄文から奈良時代へと繋がるタイムトンネルをくぐろう。\n\n実物の貝層断面標本の迫力と、1300年前の下総国分寺の屋根を飾っていた蓮華文の古瓦。\n\n博物館で古代の姿を知ったら、台地を南へ歩き、天平13年に聖武天皇の詔で築かれた『下総国分尼寺跡』へ向かおう。",
