        "f7_fragment": "奈良時代の天平13年（741年）、飢饉や疫病に苦しむ国を仏教の力で鎮めるため、聖武天皇は全国に僧寺（国分寺）と尼寺（国分尼寺）を建てる詔を発した。",
        "f7_full": "奈良時代の天平13年（741年）、飢饉や疫病に苦しむ国を仏教の力で鎮めるため、聖武天皇は全国に僧寺（国分寺）と尼寺（国分尼寺）を建てる詔を発した。下総国の尼寺『法華滅罪之寺』がどこにあったのか長らく謎だったが、昭和7年（1932年）の発掘調査で『尼寺』と墨で書かれた土器が出土し、ついにこの場所だと証明された。版築（はんちく）で固められた金堂・講堂の基壇跡に立ってみよう。\n\n芝生広場の中に復元表示された奈良時代の金堂・講堂の巨大な基壇跡と礎石の並び。\n\n尼寺跡から南東へ徒歩7分。対をなす国家鎮護の大寺院『下総国分寺』で旅の結びを迎えよう。",
