        "f7_full": "下総国分尼寺跡から谷を越えた高台に鎮座する『国分山 下総国分寺』。1300年前の奈良時代、ここには金堂と巨大な七重塔が法隆寺のように並び立ち、東京湾や江戸川を行き交う舟からもその偉容が望めたという。東京大学教授で建築家の岸田日出刀が設計した端正な本堂の前に立ち、4000年前の縄文の貝塚から天平の国分寺まで、なぜ人々はこの台地を選び続けたのか——その答えを、あなたが選ぶ。\n\n古代の金堂跡の上に立つモダンで気品ある本堂と、今も畑や境内に眠る天平の大伽藍の記憶。",
