        "f7_full": "梨街道から一歩南の緑へ入ると、長田谷津へ落ち込む斜面の上に『大町日枝神社』が鎮座している。山の神・水の神である大山咋神（おおやまくいのかみ）を祀る旧大町村の鎮守だ。境内を歩くと、天保3年（1832年）の小さな狛犬や安政5年（1858年）の常夜灯、さらに明治17年（1884年）の愛らしい子連れの狛犬が並び、江戸時代からこの台地を耕してきた村人たちの厚い信仰を今に伝えている。\n\n天保・安政・明治と時代ごとの表情を見せる石造りの狛犬たちと、谷津を見下ろす静かな杜。\n\n神社の脇から谷底へ続く坂道を下り、東山魁夷画伯も愛した湧水の聖域『大町公園（自然観察園）』の木道へ入ろう。",
