        "f7_full": "松虫寺の境内から歩いてわずか1分、里山の木立の中にひっそりと佇む『GARDEN CAFE MAZMUSHI COFFEE（マツムシコーヒー）』。心地よいレコードの音楽が流れる店内と森のテラスでは、丁寧に焙煎されたスペシャルティコーヒーと自家製の焼き菓子が待っている。京成高砂から始まった北総線の旅の終着点で、なぜ1300年前の松虫姫の祈りが今も新しい街と人の心を癒やし続けているのか——その答えを、あなたが選ぶ。\n\n松虫寺の森と一体になった緑のガーデンテラスと、芳醇な自家焙煎珈琲の深い余韻。",
