        "f7_full": "潮の香りが強くなると、視界が大きく開けて『小樽運河』の浅草橋街園に出る。大正12年（1923年）に完成したこの運河が緩やかにカーブしているのは、大地を掘ったのではなく、海岸の沖合を曲線状に埋め立てて陸地との間に水路を造った日本唯一の『埋め立て式運河』だからだ。対岸にずらりと並ぶ木骨石造の倉庫群と、散策路の63基のガス灯が暗い水面にオレンジ色の光の柱を落とす中、カモメの声と海風に耳を澄ませよう。あなたの心に刻まれた小樽の記憶を、4つの選択肢から選ぼう。\n\nなぜ運河がまっすぐではなく優美な曲線を描いているのかという地形の秘密と、水面に揺れるガス灯の灯り。",
