        "f7_fragment": "角館駅から西へ歩いて8分、商人の町『外町（とまち）』の通りに入ると、風に乗って熟成した味噌と醤油の芳醇な香りが漂ってくる。",
        "f7_full": "角館駅から西へ歩いて8分、商人の町『外町（とまち）』の通りに入ると、風に乗って熟成した味噌と醤油の芳醇な香りが漂ってくる。嘉永6年（1853年）創業の『安藤醸造 本店』だ。店の奥へ進むと、大火から家宝と蔵を守るために明治25年（1892年）に築かれた、東北最古級の『レンガ造り座敷蔵』が現れる。外側は西洋の赤レンガ積みでありながら、内部は総漆塗りの格天井と襖絵が広がる和洋折衷の空間だ。湧き水『せせらぎ』と、焦がしキャラメルのように甘じょっぱい名物『しょうゆソフト』を味わいながら、最初のしるしを刻む。\n\n赤レンガの外壁の扉をくぐった瞬間に現れる、豪華絢爛な和の座敷蔵と醤油ソフトの絶妙なコク。\n\n安藤醸造から北東へ徒歩4分、5つの白壁土蔵がずらりと並ぶ田町の『あきた角館 西宮家』へ向かおう。",
