        "f7_full": "商人町を抜けて『内町（うちまち）』へ入った瞬間、視界を縁取るのは渋墨（しぶすみ）で塗られた深い黒板塀と、空を覆う枝垂れ桜の並木だ。その入り口に建つ『角館樺細工（かばざいく）伝承館』では、今から200年以上前の天明年間、角館の下級武士たちが暮らしを支える手内職として始めた伝統工芸『樺細工』の技に出会える。山桜の樹皮を膠（にかわ）と熱した鉄ゴテだけで木の芯に貼り付け、飴色の光沢を生み出す職人の手元をのぞいてみよう。\n\n熱した鉄ゴテが山桜の皮に触れたときに立ちのぼる微かな木の香りと、呼吸するように湿気を防ぐ茶筒の精密さ。\n\n伝承館を出てすぐ目の前、黒板塀が最も美しく連なる武家屋敷通りを北へ1分歩き、『青柳家』の薬医門をくぐろう。",
