        "f7_full": "華やかな明治・大正の洋館群が並ぶ追手門広場から北へ通りを渡ると、空気が凛と張り詰める。慶長16年（1611年）に津軽為信・信枚父子が築城した弘前城の表門『三の丸追手門（おうてもん）』だ。400年以上一度も火災に遭わず当時の姿を守り抜いてきた国指定重要文化財の櫓門が、静かな外濠の水面に白漆喰の壁と銅瓦の屋根を映している。分厚いケヤキの扉に打ち付けられたゴツゴツとした鉄鋲（てつびょう）や、銃眼を兼ねた矢狭間（やざま）、そして樹齢100年を超えるソメイヨシノと黒松の深い緑を見上げよう。\n\n明治の洋館群のすぐ目の前に、400年前の鉄鋲と白漆喰がそのまま残る江戸初期の巨大な櫓門がそびえる時代対比。\n\n追手門から西へ濠端を歩いて5分。崖の上から津軽富士・岩木山を一望する別邸庭園『藤田記念庭園』で旅を結ぼう。",
