        "f7_full": "小野川に架かる忠敬橋のたもとへ出ると、江戸風の木造商家が連なる中に、東京駅を思わせる鮮やかな赤レンガと白い花崗岩の洋館がそびえている。大正3年（1914年）に川崎銀行佐原支店として建てられた『三菱館（旧三菱銀行佐原支店本館）』だ。角地に緑青色のドーム屋根を頂いたルネサンス様式の建物は、当時の佐原が利根川水運と醸造業でどれほど莫大な富を集めていたかを物語っている。中へ入ると、大理石の銀行カウンターと2階吹き抜けの回廊が当時のまま残されている。\n\n柳が揺れる和の川辺に赤レンガのドーム建築が違和感なく溶け込む風景と、2階回廊から見下ろす吹き抜けホールの優雅さ。\n\n三菱館から小野川の柳並木に沿って南へ徒歩2分。50歳から日本中を歩いた測量家の原点『伊能忠敬旧宅』を訪ねよう。",
