        "f7_full": "黒門を抜け、視界が開けた瞬間に思わず足が止まる。広い内堀の水鏡の向こうに、上半分を白漆喰、下半分を黒漆塗りの下見板で覆った五重六階の『国宝 松本城』が堂々とそびえ立っている。文禄年間（1593〜1594年頃）、豊臣秀吉の信任厚い石川数正・康長父子が築いた日本最古の五重現存天守だ。よく見ると、鉄砲戦に備えた武骨な『大天守・乾小天守』の横に、江戸初期の泰平の世に増築された朱塗りの欄干を持つ優美な『月見櫓（つきみやぐら）』が寄り添っており、戦国から平和な時代への移り変わりがひとつの城に刻まれている。\n\n北アルプスの白い峰々と、水堀に逆さに映り込む漆黒の天守が織りなす絵画のようなコントラスト。\n\n松本城からさらに北へ歩いて7分。もうひとつの国宝、和の大工が天使の彫刻を掲げた『旧開智学校校舎』で旅を結ぼう。",
