        "f7_fragment": "漆黒の松本城から北へ歩くと、今度は青白い漆喰壁に八角形の塔屋を載せた不思議で愛らしい建物が現れる。",
        "f7_full": "漆黒の松本城から北へ歩くと、今度は青白い漆喰壁に八角形の塔屋を載せた不思議で愛らしい建物が現れる。明治9年（1876年）に建てられ、近代学校建築として日本初の国宝に指定された『旧開智学校校舎』だ。文明開化の時代、「松本に日本一の小学校を造ろう」と建築費の実に7割を町民たちの寄付で集め、地元の宮大工棟梁・立石清重が東京や横浜の洋館を見よう見まねで設計した『擬洋風（ぎようふう）建築』の傑作である。正面バルコニーの上で、寺社彫刻の雲の上に2人の可愛らしい『天使』が校名看板を掲げる姿を見上げながら、あなたの心に響いた松本の美意識を選ぼう。\n\n日本の伝統的な瓦屋根と唐破風の下で、宮大工が彫った木彫りのキューピッド（天使）が看板を支えている唯一無二の意匠。",
