        "f7_full": "伊勢市駅の改札を出て正面の参道を南へ歩き、堀川に架かる木造の『火除橋（ひよけばし）』を渡ると、街の喧騒がすっと遠のく。左手にそびえる清盛楠（きよもりぐす）に会釈し、第一鳥居をくぐって大粒の玉砂利をサクサクと踏みしめながら巨木の杜を進もう。ここ『伊勢神宮 外宮（豊受大神宮）』は、天照大御神のお食事を司る豊受大御神（とようけのおおみかみ）をお祀りし、古来「まず外宮から参拝する」という『外宮先祭（げくうせんさい）』の習わしが守られてきた聖域だ。白い絹の御幌（みとばり）が風に揺れる正宮の前で手を合わせ、最初のしるしを刻む。\n\n1500年もの間、一日たりとも欠かさず朝と夕の二度、火鑽具（ひきりぐ）でおこした火で調理した食事を神様に捧げる『日別朝夕大御饌祭』が今も続けられている事実。\n\n正宮から北御門方面へ戻り、勾玉池のほとりに佇む『式年遷宮記念 せんぐう館』へ徒歩5分。",
