        "f7_full": "松江駅から松江大橋を渡り（ぐるっと松江レイクラインバスで京橋下車も心地よい）、堀川のひとつである京橋川のたもとに立つと、石畳の角に端正な暖簾を掲げる『風流堂（ふうりゅうどう）京橋店』が見えてくる。ここ松江は、江戸時代後期の大名茶人・松平治郷（不昧公）が茶の湯を広め、京都・金沢と並ぶ日本三大菓子処となった街だ。明治23年（1890年）創業の風流堂は、一度は製法が途絶えていた不昧公好みの銘菓『山川（やまかわ）』を大正時代に復刻させた名店である。紅葉の山と白い川を表した紅白の打ち菓子や、丁寧に皮をむいた小豆餡を大和芋の生地で包んだ『朝汐』に、最初のしるしを刻む。\n\n口に含んだ瞬間にすっと溶ける紅白の『山川』の繊細な口どけと、町人の普段のお茶にまで上生菓子が根づいている水都の文化。\n\n京橋を渡って北西へ歩いて2分。緑青色のドームとギリシャ列柱がそびえる『カラコロ工房』へ向かおう。",
