        "f7_full": "松江城の北側、内堀に沿って樹齢数百年の老松と武家屋敷の切妻屋根が連なる『塩見縄手（しおみなわて）』へ出る。堀川をゆく遊覧船の船頭唄が水面に響くこの通りで、明治23年（1890年）に英語教師として来日したラフカディオ・ハーン（小泉八雲）は妻・セツとともに武家屋敷に暮らした。『小泉八雲記念館』で愛用の机や片眼鏡、直筆原稿を見つめ、すぐ隣の『小泉八雲旧居』の三方の小庭にたたずめば、八雲が「神々の国の首都」と呼んで愛した松江の風と物音がそのまま聞こえてくる。\n\nわずか1年3か月の松江滞在でありながら、八雲の生涯の代表作『怪談』や『知られぬ日本の面影』の原風景がこの堀川沿いの武家屋敷に凝縮されていること。",
