        "f7_full": "鯉の泳ぐ水路のすぐ先に、静かな表門を構える『湧水庭園 四明荘（しめいそう）』がある。明治後期に地元の医師が別邸として建てたお屋敷で、一歩座敷へ上がると、四方の障子がすべて開け放たれたその名の通り明るい視界が広がる。最大の見どころは、1日約3,000トンもの湧水が池底の砂を巻き上げながら湧き続ける深い池の真上に、主屋の畳縁（縁側）がせり出すように造られていることだ。縁側に腰を下ろして足をぶらつかせ、湧水で淹れた冷たい島原緑茶をいただきながら水面を渡る風を感じよう。\n\n池のほとりではなく『湧水池の真上』に縁側が浮かんでおり、座敷に座ったまま足元の水中を泳ぐ鯉を見下ろせる唯一無二の建築構造。\n\n四明荘から南東へ歩いて12分。共同洗い場『浜の川湧水』と大正4年創業の甘味処『元祖かんざらし 銀水』で旅を結ぼう。",
