        "cover_image_url": "/images/momoyamadai/spot1.png",
        "f7_fragment": "新御堂筋の掘割に抱かれた桃山台駅の大きな歩道橋を渡ると、すぐ眼下に周囲約1キロメートルの広大な水面『春日大池』が開ける。",
        "f7_full": "新御堂筋の掘割に抱かれた桃山台駅の大きな歩道橋を渡ると、すぐ眼下に周囲約1キロメートルの広大な水面『春日大池』が開ける。朱色の欄干が映える太鼓橋の周りにはスイレンの浮葉が広がり、カモやカワセミが水辺のデッキで羽を休めている。昭和37年（1962年）に始まった日本初の大規模ニュータウン開発よりも遥か昔、江戸時代の新田開発で千里丘陵の谷筋を堰き止めて造られた農業用ため池が、そのまま都市公園の核として受け継がれた水辺だ。\n\n近代的なベッドタウンの象徴に見える池が、実は江戸時代の春日新田開発で造られた古い灌漑用ため池であり、当時の谷の地形がそのまま残されていること。\n\n池の岸に沿って東へ徒歩6分。開発前の丘陵の記憶を伝える孟宗竹のトンネル『千里の竹林』へ入ろう。",
