        "f7_full": "駅前の舗装路を離れて西へわずか数分歩くと、白い幹のシラカバと背の低いエゾイソツツジ、ハイマツが地面を覆う原生林の入口に立つ。深呼吸をすると肺の奥までひんやりと澄んだ森の冷気が流れ込むのに、すぐ足元を流れる硫黄山川の水面からは、上流の硫黄山から湧き出た強酸性の温泉水が混じって幽かな湯気とツンと甘い硫黄の匂いが立ちのぼっている。凍てつく森と熱い火山の記憶が、ここでは同じ空気の中に溶け合っている。\n\n通常は標高の高い高山帯でしか見られないハイマツやエゾイソツツジがこのような平地の駅近くで群生しているのは、硫黄山から噴き出す火山ガスと強酸性の土壌が他の高木の侵入を拒んできた証左でもある。\n\n原生林の冷気で頬を冷やしたら東北東へ徒歩2分。白樺木立のなかで甘い香りを漂わせる『森のホール』へ戻ろう。",
