    "description": "何本もの新幹線と在来線が絶え間なく滑り込み、秒単位で人が行き交う巨大ターミナル・大宮駅。その東口の眠らない純喫茶の喧騒から歩き出してわずか数分、街の空気はケヤキの大樹が頭上を覆う緑のトンネルへと切り替わる。醤油の焦げる香ばしい煙、白い玉砂利を踏む音、そして神社の最深部で音もなく湧き出す太古の泉へ。一歩北へ進むごとに自分の歩く速度が落ち、いつしか呼吸が深く静まっていく「都市の減速」を味わう散歩道。",
